{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have an aws_s3_bucket_public_access_block resource configured, leaving it potentially exposed to public access if ACLs or policies are misconfigured."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.b",
      "severity": "HIGH",
      "explanation": "The S3 bucket lacks server-side encryption configuration. Data at rest is not encrypted using SSE-KMS or SSE-S3, violating data protection standards."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.b",
      "severity": "HIGH",
      "explanation": "Versioning is not enabled on the S3 bucket, which prevents recovery from accidental deletion or overwrites and reduces auditability."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "Server access logging is not configured for the S3 bucket, hindering the ability to track requests made against the bucket for security auditing."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "b" {
  bucket = "my-tf-test-bucket-ggff"
  acl    = "private"
}

resource "aws_s3_bucket_public_access_block" "b" {
  bucket                  = aws_s3_bucket.b.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "b" {
  bucket = aws_s3_bucket.b.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "b" {
  bucket = aws_s3_bucket.b.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "b" {
  bucket        = aws_s3_bucket.b.id
  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = "log/"
}

resource "aws_s3_bucket" "log_bucket" {
  bucket = "my-tf-test-log-bucket-ggff"
  acl    = "log-delivery-write"
}
",
  "fix_summary": "Added aws_s3_bucket_public_access_block to prevent public exposure, aws_s3_bucket_server_side_encryption_configuration to enforce KMS encryption, aws_s3_bucket_versioning to enable versioning, and aws_s3_bucket_logging (along with a dedicated log bucket) to enable access logging."
}
